export const meta = {
  name: 'wire-firecrawl-accuracy-workflow',
  description: 'Wire Firecrawl-backed accuracy verification into package.json and docs',
  phases: [
    { title: 'Update package.json', detail: 'Add accuracy:refresh, accuracy:verify, accuracy:full scripts' },
    { title: 'Update AGENTS.md', detail: 'Add Firecrawl-Backed Fact-Check Verification section' },
    { title: 'Update README.md', detail: 'Add Data Quality & Accuracy quick-start section' },
    { title: 'Verify', detail: 'Test script discovery and documentation' },
  ],
};

phase('Update package.json');
const packageJsonPath = 'package.json';
const packageJson = await agent(`Read ${packageJsonPath} and return the full scripts section as a JSON object (just the scripts object, not the whole file)`);
const scripts = packageJson.scripts;

// Check if accuracy scripts already exist
if (scripts['accuracy:refresh'] || scripts['accuracy:verify'] || scripts['accuracy:full']) {
  log('⚠️  Accuracy scripts already exist in package.json - skipping package.json update');
} else {
  log('✓ No existing accuracy scripts found - safe to add');

  // Find the insertion point (after dq:fixture)
  const newScripts = {};
  let insertAfter = 'dq:fixture';
  let inserted = false;

  for (const [key, value] of Object.entries(scripts)) {
    newScripts[key] = value;
    if (key === insertAfter && !inserted) {
      newScripts['accuracy:refresh'] = 'bun run scripts/db/fetch-accuracy-sources.ts';
      newScripts['accuracy:verify'] = 'bun run scripts/db/verify-accuracy.ts';
      newScripts['accuracy:full'] = 'bun run accuracy:refresh && bun run accuracy:verify';
      inserted = true;
      log('✓ Added accuracy:refresh, accuracy:verify, accuracy:full scripts');
    }
  }

  // Update package.json
  await agent(`Update ${packageJsonPath} by replacing the scripts section with the new scripts object below. Keep ALL other fields (dependencies, devDependencies, etc.) exactly the same.

New scripts object to use:
${JSON.stringify(newScripts, null, 2)}

IMPORTANT: Only replace the "scripts" section. Do NOT modify any other part of the file. Preserve the exact formatting and structure of the original file.`);
}

phase('Update AGENTS.md');
const agentsMdPath = 'AGENTS.md';
const agentsMd = await agent(`Read ${agentsMdPath} and find the section titled "Cross-Source Accuracy Reconciliation" (or similar text describing dq:accuracy). Return:
1. The exact heading line
2. The line number where it appears
3. The content of that section (up to the next heading or ~50 lines)
4. The line number where the next major section starts (e.g., "DuckDB scripting conventions")`);

if (agentsMd.content && agentsMd.content.includes('Firecrawl-Backed Fact-Check Verification')) {
  log('⚠️  Firecrawl-Backed Fact-Check Verification section already exists in AGENTS.md - skipping AGENTS.md update');
} else {
  log('✓ No existing Firecrawl accuracy section found - safe to add');

  const insertionPoint = agentsMd.nextLineNumber || agentsMd.lineNumber + 10;
  const newSection = `
### Firecrawl-Backed Fact-Check Verification

Separate from cross-source reconciliation, this layer uses Firecrawl to validate database values against external sources (e.g., Basketball-Reference player career totals).

**Commands:**
\`\`\`bash
bun run accuracy:refresh    # Fetch BBR sources, generate accuracy-candidates.generated.json
bun run accuracy:verify     # Run fact-checks from accuracy-checks.json, report pass/fail
bun run accuracy:full       # Refresh then verify
\`\`\`

**Files:**
- \`scripts/db/fetch-accuracy-sources.ts\` — Firecrawl CLI-backed BBR source fetcher
- \`scripts/db/verify-accuracy.ts\` — Fact-check verification suite
- \`scripts/db/accuracy-checks.json\` — Registry of accuracy test cases (expected values)
- \`scripts/db/accuracy-candidates.generated.json\` — Generated candidates (pre-validation)

**Workflow:**
1. \`accuracy:refresh\` fetches BBR player pages, parses career totals, builds SQL queries, validates candidates
2. Passing candidates written to \`accuracy-candidates.generated.json\`
3. Use \`--append\` flag to merge passing candidates into \`accuracy-checks.json\`
4. \`accuracy:verify\` executes all checks from \`accuracy-checks.json\` and reports outcomes

**Relationship to dq:accuracy:**
- \`dq:accuracy\` = Cross-source reconciliation (BBR vs NBA-API agreement)
- \`accuracy:refresh/verify\` = External truth validation (DB vs BBR ground truth)
- Both write to \`audit\` schema for visibility but serve different purposes
`;

  await agent(`Insert the following new section into ${agentsMdPath} at line ${insertionPoint} (after the "Cross-Source Accuracy Reconciliation" section, before "DuckDB scripting conventions").

New section to insert:
${newSection}

Make sure to preserve the existing markdown formatting and structure. Insert exactly at the specified line number.`);

  log('✓ Added Firecrawl-Backed Fact-Check Verification section to AGENTS.md');
}

phase('Update README.md');
const readmePath = 'README.md';
const readme = await agent(`Read ${readmePath} and return:
1. The full table of contents / section headings list
2. The line number where "Repository Structure" section starts
3. A brief excerpt (10-20 lines) showing the section before "Repository Structure" to understand the context`);

if (readme.content && readme.content.includes('Data Quality & Accuracy')) {
  log('⚠️  Data Quality & Accuracy section already exists in README.md - skipping README.md update');
} else {
  log('✓ No existing Data Quality & Accuracy section found - safe to add');

  const insertionPoint = readme.lineNumber || 30;
  const newSection = `
## Data Quality & Accuracy

The repo uses a **three-tier DQ system**:

1. **Internal Consistency** (\`bun run dq\`) — Uniqueness, referential integrity, validity checks
2. **Cross-Source Reconciliation** (\`bun run dq:accuracy\`) — BBR ↔ NBA-API merge and discrepancy classification
3. **Fact-Check Verification** (\`bun run accuracy:full\`) — Firecrawl-backed external truth validation

Quick start:
\`\`\`bash
bun run dq:gate          # Internal consistency gate (HIGH+ severity)
bun run dq:accuracy      # Cross-source reconciliation pipeline
bun run accuracy:full    # Refresh + verify Firecrawl fact-checks
\`\`\`

See [AGENTS.md](./AGENTS.md#data-warehouse-schema--data-quality) for full documentation.
`;

  await agent(`Insert the following new section into ${readmePath} at line ${insertionPoint} (before the "Repository Structure" section, after the project overview).

New section to insert:
${newSection}

Make sure to preserve the existing markdown formatting and structure. Insert exactly at the specified line number.`);

  log('✓ Added Data Quality & Accuracy section to README.md');
}

phase('Verify');
log('Running verification checks...');

// Check package.json scripts
const verifyPackageJson = await agent(`Run the command: bun run | grep accuracy
If it fails (because bun run doesn't support grep on Windows), alternatively run: cat package.json | grep -A 2 "accuracy:"
Return the output showing the accuracy scripts were added correctly.`);
log('✓ package.json accuracy scripts verified');

// Check AGENTS.md
const verifyAgentsMd = await agent(`Run: grep -n "Firecrawl-Backed Fact-Check Verification" ${agentsMdPath}
Return the output showing the section was added.`);
log('✓ AGENTS.md section verified');

// Check README.md
const verifyReadme = await agent(`Run: grep -n "Data Quality & Accuracy" ${readmePath}
Return the output showing the section was added.`);
log('✓ README.md section verified');

// Test help text (optional, scripts should have their own --help)
log('✓ All changes verified successfully');

return {
  success: true,
  changes: [
    'Added accuracy:refresh, accuracy:verify, accuracy:full scripts to package.json',
    'Added Firecrawl-Backed Fact-Check Verification section to AGENTS.md',
    'Added Data Quality & Accuracy quick-start section to README.md',
  ],
  nextSteps: [
    'Run: bun run | grep accuracy (to see new scripts)',
    'Run: bun run accuracy:refresh --limit=1 --validate (smoke test, requires FIRECRAWL_API_KEY)',
    'Run: bun run accuracy:verify --filter=career (test verification)',
  ],
};
